/* @lc app=leetcode id=1367 lang=kotlin */ class Solution{fun m(h: ListNode?, t: TreeNode?): Boolean = h == null || t != null && h.`val` == t.`val` && (m(h.next, t.left) || m(h.next, t.right)) fun isSubPath(head: ListNode?, root: TreeNode?): Boolean = root != null && (m(head, root) || isSubPath(head, root.left) || isSubPath(head, root.right)) }